1428	    execute: async ({module: moduleId, name, content, url, mime}) => {
1429	      const mod = cellHelpers.resolveModule(moduleId);
1430	      if (!mod)
1431	        return { output: 'ERROR: no live module ' + moduleId + ' (glob /src/*.js to see module ids; write the module first)' };
1432	      if ((content == null) === (url == null))
1433	        return { output: 'ERROR: provide exactly one of content or url' };
1434	      const extMime = ({js: 'text/javascript', mjs: 'text/javascript', cjs: 'text/javascript', css: 'text/css', json: 'application/json', gz: 'application/gzip', wasm: 'application/wasm', svg: 'image/svg+xml', txt: 'text/plain', md: 'text/markdown'})[(name.split('.').pop() || '').toLowerCase()];
1435	      let file;
1436	      if (url != null) {
1437	        let res;
1438	        try {
1439	          res = await fetch(url);
1440	        } catch (e) {
1441	          return { output: 'ERROR: fetch ' + url + ' failed: ' + (e && e.message || e) };
1442	        }
1443	        if (!res.ok)
1444	          return { output: 'ERROR: fetch ' + url + ' \u2192 HTTP ' + res.status };
1445	        const blob = await res.blob();
1446	        file = new File([blob], name, { type: mime || extMime || blob.type || 'application/octet-stream' });
1447	      } else {
