1452	      } catch (e) {
1453	        return { output: 'ERROR: attach failed: ' + (e && e.message || e) };
1454	      }
1455	      return { output: 'Attached ' + name + ' (' + file.size + ' bytes, ' + file.type + ') to ' + moduleId + '. Cells read it with FileAttachment(' + JSON.stringify(name) + ').' };
1456	    }
